-- Align fictional organisation, venue, and role details without touching user records.
create table if not exists public.demo_catalog_entries (
  entry_id text primary key,
  kind text not null check (kind in ('player', 'organisation', 'venue', 'opportunity', 'game')),
  payload jsonb not null check (jsonb_typeof(payload) = 'object'),
  created_at timestamptz not null default now()
);
create index if not exists demo_catalog_entries_kind_idx on public.demo_catalog_entries(kind);
revoke all on public.demo_catalog_entries from anon, authenticated;
grant select on public.demo_catalog_entries to service_role;
on conflict (entry_id) do update set kind = excluded.kind, payload = excluded.payload;
